/* Exact bounded arithmetic models. Checkpoints express dependencies, not electrical time. */
"use strict";
(()=>{
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const cp=x=>JSON.parse(JSON.stringify(x));
const txt=(x,y,s,cls='ar-label')=>{const label=esc(s).replace(/([a-zA-Z])([0-9])/g,'$1<tspan class="ar-index" baseline-shift="sub">$2</tspan>').replace(/2\^([0-9]+)/g,'2<tspan class="ar-index" baseline-shift="super">$1</tspan>');return `<text x="${x}" y="${y}" class="${cls}">${label}</text>`;};
const bit=(v,i)=>(v>>i)&1, bits=(v,n)=>v.toString(2).padStart(n,'0'), signed=(v,n)=>v>=2**(n-1)?v-2**n:v;
const box=(x,y,w,h,fill='#eef4f7')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="7" fill="${fill}" stroke="#7795a4"/>`;
const wire=(ps,on=false)=>`<polyline points="${ps.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${on?'#217f7d':'#839aa7'}" stroke-width="${on?3:2}"/>`;
const node=(x,y)=>`<circle cx="${x}" cy="${y}" r="3.5" fill="#537789"/>`;
const symbol=(x,y,kind,label,active=false)=>{
 let path=['and','nand'].includes(kind)?`M${x},${y} L${x+30},${y} A26,26 0 0 1 ${x+30},${y+52} L${x},${y+52} Z`:
 kind==='mux'?`M${x},${y} L${x+56},${y+10} L${x+56},${y+42} L${x},${y+52} Z`:
 `M${x},${y} Q${x+30},${y} ${x+56},${y+26} Q${x+30},${y+52} ${x},${y+52} Q${x+17},${y+26} ${x},${y} Z`;
 let b=`<path d="${path}" fill="${active?'#d8eeea':'#f7fafb'}" stroke="#476f82" stroke-width="2"/>`;
 if(kind==='xor')b+=`<path d="M${x-7},${y} Q${x+10},${y+26} ${x-7},${y+52}" fill="none" stroke="#476f82" stroke-width="2"/>`;
 if(kind==='nand')b+=`<circle cx="${x+61}" cy="${y+26}" r="5" fill="white" stroke="#476f82" stroke-width="2"/>`;
 if(['or','xor'].includes(kind)){const start=kind==='xor'?x-7:x;b+=wire([[start,y+13],[x+6.375,y+13]])+wire([[start,y+39],[x+6.375,y+39]]);}
 return b+txt(x+18,y+32,label,'ar-gate');
};
function svg(b,h=420,kind='arithmetic-circuit'){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 ${h}" role="img" data-model-kind="${kind}" aria-label="Exact arithmetic checkpoint">${b}</svg>`;}
function fullSVG(s){const p=s.p??'?',g=s.g??'?',h=s.h??'?',sum=s.sum??'?',carry=s.carry??'?';let b=txt(30,32,'Full adder: parity and weighted carry')+txt(30,68,'Wires meet only at marked junctions; input labels are exact bit values.');
 b+=wire([[100,150],[180,150],[180,132],[243,132]])+wire([[100,240],[160,240],[160,158],[243,158]])+wire([[180,150],[180,277],[250,277]])+node(180,150)+wire([[160,240],[160,303],[250,303]])+node(160,240);
 b+=wire([[306,145],[450,145],[450,132],[543,132]],s.p===1)+wire([[450,145],[450,277],[550,277]],s.p===1)+node(450,145)+wire([[100,355],[490,355],[490,158],[543,158]])+wire([[490,355],[490,303],[550,303]])+node(490,355);
 b+=wire([[306,290],[675,290],[675,263],[750,263]],s.g===1)+wire([[606,290],[710,290],[710,289],[750,289]],s.h===1)+wire([[606,145],[890,145]],s.sum===1)+wire([[806,276],[890,276]],s.carry===1);
 b+=symbol(250,119,'xor','⊕',s.p!==undefined)+symbol(250,264,'and','∧',s.g!==undefined)+symbol(550,119,'xor','⊕',s.sum!==undefined)+symbol(550,264,'and','∧',s.h!==undefined)+symbol(750,250,'or','∨',s.carry!==undefined);
 b+=txt(30,156,'a = '+s.a,'ar-math')+txt(30,246,'b = '+s.b,'ar-math')+txt(30,361,'c = '+s.c,'ar-math')+txt(335,125,'p = '+p,'ar-math')+txt(340,321,'g = '+g,'ar-math')+txt(620,321,'h = '+h,'ar-math')+txt(900,151,'s = '+sum,'ar-math')+txt(845,312,'out = '+carry,'ar-math');return svg(b,410,'full-adder-gates');}
function rippleSVG(s,subtract=false){let b=txt(30,32,subtract?'XOR-controlled subtraction: complemented B and carry one':'Ripple adder: carry connects adjacent full-adder ports')+txt(30,68,'Least significant column is on the left. “?” means not yet established.');const w=840/s.n,x0=90;
 for(let i=0;i<s.n;i++){let x=x0+i*w,c=s.columns[i],known=Boolean(c);b+=`<g data-entity="column-${i}">${box(x,175,w-28,75,known?'#d9eeea':'#f0f4f7')}${txt(x+16,208,'FA '+i,'ar-math')}${txt(x+16,233,known?'settled':'pending')}${wire([[x+18,125],[x+18,175]])}${wire([[x+w-48,145],[x+w-48,175]])}${txt(x+4,112,'a:'+bit(s.a,i),'ar-math')}${txt(x+w-65,138,'b:'+bit(s.effectiveB,i),'ar-math')}${wire([[x+(w-28)/2,250],[x+(w-28)/2,302]],known&&c.sum===1)}${txt(x+10,334,'s:'+ (known?c.sum:'?'),'ar-math')}</g>`;
  if(i===0)b+=wire([[30,214],[x,214]],s.c===1)+txt(30,192,'c:'+s.c,'ar-math');
  b+=wire([[x+w-28,214],[i<s.n-1?x+w:x+w+25,214]],known&&c.out===1)+txt(x+w-33,278,'c:'+ (known?c.out:'?'),'ar-math');
 }
 b+=txt(30,380,'A='+bits(s.a,s.n)+'; effective B='+bits(s.effectiveB,s.n)+'; established columns='+s.columns.length,'ar-math');return svg(b,420,'ripple-carry-chain');}
function prefixSVG(s){const w=880/s.n;let b=txt(30,30,'Ordered prefix carry composition')+txt(30,64,'Every edge joins contiguous high / low intervals; the lower carry enters the higher group.');
 s.levels.forEach((row,k)=>{const y=95+k*92;for(let i=0;i<s.n;i++){const x=55+i*w,r=row[i],active=k===s.levels.length-1;b+=`<g data-entity="prefix-${k}-${i}">${box(x,y,w-16,62,active?'#d7eeeb':'#f0f4f7')}${txt(x+9,y+23,'['+r.high+':'+r.low+']','ar-small')}${txt(x+9,y+47,'G='+r.g+' P='+r.p,'ar-small')}</g>`;if(k){const step=2**(k-1);b+=wire([[x+(w-16)/2,y-30],[x+(w-16)/2,y]]);if(i>=step)b+=wire([[55+(i-step)*w+(w-16)/2,y-30],[x+(w-16)/2,y]]);}}});
 const y=95+s.levels.length*92; b+=txt(35,y+10,'Final output carry: '+(s.output??'?')+'; composition stages completed: '+(s.levels.length-1),'ar-small');return svg(b,y+46,'ordered-prefix-network');}
function selectSVG(s){let b=txt(30,32,'Carry-select: duplicate first, select only after low carry is known')+txt(30,68,'Upper outputs include their outgoing carry; the selector carries a whole result bundle.');
 b+=box(75,178,245,92,s.low!==undefined?'#d9eeea':'#eef4f7')+txt(95,206,'Low 4-bit ripple')+txt(95,239,'Slo '+(s.low===undefined?'?':bits(s.low,4))+'; C4 '+(s.c4??'?'),'ar-math');
 b+=box(445,105,275,85,s.high0!==undefined?'#d9eeea':'#eef4f7')+txt(465,133,'High block: assume C4 = 0')+txt(465,165,'bundle '+(s.high0??'?'),'ar-math');
 b+=box(445,270,275,85,s.high1!==undefined?'#d9eeea':'#eef4f7')+txt(465,298,'High block: assume C4 = 1')+txt(465,330,'bundle '+(s.high1??'?'),'ar-math');
 b+=wire([[720,147],[770,147],[770,199],[805,199]],s.c4===0)+wire([[720,312],[790,312],[790,225],[805,225]],s.c4===1)+symbol(805,186,'mux','M',s.result!==undefined)+wire([[320,224],[390,224],[390,385],[833,385],[833,233]],s.c4===1)+txt(465,410,'Select = C4; 4 sum bits and final carry are chosen together.')+wire([[861,212],[940,212]],s.result!==undefined)+txt(880,180,'out '+(s.highSelected??'?'),'ar-math');return svg(b,450,'carry-select-datapath');}
function compareSVG(s){const w=850/s.n;let b=txt(30,32,'Unsigned comparison: scan from the highest-weight bit')+txt(30,68,'Lower columns are inspected only while the already inspected prefix is equal.');for(let j=0;j<s.n;j++){const i=s.n-1-j,x=75+j*w,seen=j<s.inspected; b+=`<g data-entity="compare-${i}">${box(x,120,w-15,125,seen?'#dcefea':'#f1f4f7')}${txt(x+15,149,'bit '+i,'ar-math')}${txt(x+15,185,'A '+bit(s.a,i),'ar-math')}${txt(x+15,221,'B '+bit(s.b,i),'ar-math')}</g>`;if(j)b+=wire([[x-15,271],[x,271]],seen);}
 b+=txt(75,315,'Inspected prefix: '+s.inspected+' of '+s.n+' bits')+txt(75,355,'Decision: '+s.decision)+txt(75,397,'A = '+s.a+'; B = '+s.b+' (unsigned)','ar-math');return svg(b,435,'msb-comparison');}
function bcdSVG(s){let b=txt(30,32,'BCD digit correction: q is the decimal carry')+txt(30,68,'Valid digits only. The second binary carry alone is not the decimal carry.');
 b+=box(75,128,235,105,'#e9f1f5')+txt(94,158,'4-bit initial adder')+txt(94,188,'A '+s.a+' + B '+s.b+' + c '+s.c,'ar-math')+txt(94,218,'k,z: '+(s.k??'?')+','+(s.z??'?'),'ar-math');
 b+=box(380,128,275,105,s.q!==undefined?'#d9eeea':'#edf3f6')+txt(400,158,'Threshold logic')+txt(400,188,'k OR z3z2 OR z3z1','ar-math')+txt(400,218,'q = '+(s.q??'?'),'ar-math')+wire([[310,180],[380,180]],s.z!==undefined);
 b+=box(735,128,210,105,s.digit!==undefined?'#d9eeea':'#edf3f6')+txt(755,158,'Correction adder')+txt(755,188,'z + (q ? 6 : 0)','ar-math')+txt(755,218,'digit '+(s.digit??'?'),'ar-math')+wire([[655,180],[735,180]],s.q===1);
 b+=wire([[240,233],[240,280],[760,280],[760,233]],s.z!==undefined)+txt(35,311,'Low nibble z follows the lower wire.')+wire([[550,233],[550,356],[890,356]],s.q===1)+txt(585,389,'Decimal carry = q = '+(s.q??'?'),'ar-math');return svg(b,430,'bcd-two-adder-correction');}
function csaSVG(s){const w=840/s.n;let b=txt(30,32,'Carry-save compression: column-local counting')+txt(30,68,'The carry output moves exactly one weight to the left in the final binary sum.');for(let j=0;j<s.n;j++){const i=s.n-1-j,x=95+j*w,seen=s.done.includes(i),v=[s.a,s.b,s.z].map(v=>bit(v,i)); b+=txt(x+12,105,'2^'+i,'ar-math')+txt(x+16,140,v.join('  '),'ar-math')+wire([[x+18,152],[x+18,175]])+box(x,175,w-20,54,seen?'#d9eeea':'#edf3f6')+txt(x+16,209,'FA','ar-math')+wire([[x+(w-20)/2,229],[x+(w-20)/2,290]],seen)+txt(x+10,321,'S '+(seen?bit(s.sum,i):'?'),'ar-math')+txt(x+10,358,'C '+(seen?bit(s.carry,i):'?'),'ar-math');}
 b+=txt(35,400,'Unshifted C: '+s.carry+'; S: '+s.sum+'; exact total: '+(s.done.length===s.n?s.sum+2*s.carry:'pending'),'ar-math');return svg(b,440,'carry-save-columns');}
function multiplySVG(s){let b=txt(30,32,'Unsigned shifted partial-product matrix')+txt(30,68,'Columns show positional weight. Rows are shifted before they are added.');const width=2*s.n,w=840/width;for(let j=0;j<width;j++)b+=txt(125+j*w,110,2**(width-1-j),'ar-small');for(let r=0;r<s.n;r++){let y=140+r*52;b+=txt(30,y+23,'row '+r,'ar-small');for(let j=0;j<width;j++){let i=width-1-j,x=120+j*w,p=i-r,valid=p>=0&&p<s.n,val=valid?(bit(s.a,p)&bit(s.b,r)):0;b+=box(x,y,w-8,44,r<s.done?'#dcefea':'#f3f6f8')+txt(x+10,y+29,valid?val:'·','ar-math');}}
 let y=155+s.n*52;b+=txt(35,y+10,'Established rows: '+s.done+'; accumulated value '+s.total,'ar-math')+txt(35,y+47,'A='+s.a+'; B='+s.b+'; final product '+(s.done===s.n?s.total:'pending'),'ar-math');return svg(b,y+76,'partial-product-matrix');}
function divideSVG(s){let b=txt(30,32,'Unsigned long division: exact processed-prefix invariant')+txt(30,68,'Each row consumes one dividend bit, compares U with D, then retains a remainder.');const headers=['bit','prefix P','trial U','q','new Q','new R'];headers.forEach((h,i)=>b+=txt(50+i*153,115,h));s.rows.forEach((r,j)=>{const y=133+j*35;b+=box(35,y,910,31,j===s.rows.length-1?'#d9eeea':'#f0f4f7');[r.x,r.prefix,r.u,r.q,r.Q,r.R].forEach((v,i)=>b+=txt(50+i*153,y+23,v,'ar-math'));});let y=155+s.n*35;b+=txt(35,y,'D='+s.b+'; P=DQ+R: '+s.prefix+'='+s.b+'×'+s.Q+'+'+s.R,'ar-math')+txt(35,y+38,'Remainder invariant: 0 ≤ '+s.R+' < '+s.b,'ar-math');return svg(b,y+70,'division-prefix-table');}
function boothSVG(s){let b=txt(30,32,'Signed Booth recoding: transition digits and weighted rows')+txt(30,68,'Pair order is (current bit, lower bit). Accumulation uses exact signed integers.');const labels=['position','pair','digit','signed row','partial sum'];labels.forEach((h,i)=>b+=txt(45+i*180,115,h));s.rows.forEach((r,j)=>{let y=133+j*43;b+=box(30,y,930,38,j===s.rows.length-1?'#d9eeea':'#f0f4f7');[r.i,r.pair,r.d,r.row,r.total].forEach((v,i)=>b+=txt(45+i*180,y+26,v,'ar-math'));});let y=160+s.n*43;b+=txt(35,y,'Signed A = '+s.as+'; signed B = '+s.bs+'; total = '+s.total,'ar-math')+txt(35,y+38,'The n+1-bit signed temporary can represent the positive magnitude of the minimum negative value.');return svg(b,y+70,'signed-booth-rows');}
function nandSVG(s){let b=txt(30,32,'Authenticated NAND network: difference and borrow')+txt(30,68,'Circles mark inversion. The final inverter is a NAND with its two inputs tied.');
 b+='<g transform="translate(0 35)">';b+=symbol(240,150,'nand','∧',s.t!==undefined)+symbol(475,80,'nand','∧',s.u!==undefined)+symbol(475,255,'nand','∧',s.v!==undefined)+symbol(745,150,'nand','∧',s.F1!==undefined)+symbol(745,300,'nand','∧',s.F2!==undefined);
 b+=wire([[90,110],[180,110],[180,163],[240,163]])+wire([[90,320],[170,320],[170,189],[240,189]])+wire([[180,110],[180,65],[430,65],[430,93],[475,93]])+node(180,110)+wire([[170,320],[170,375],[430,375],[430,294],[475,294]])+node(170,320);
 b+=wire([[306,176],[380,176],[380,119],[475,119]],s.t===1)+wire([[380,176],[380,268],[475,268]],s.t===1)+node(380,176)+wire([[541,106],[665,106],[665,163],[745,163]],s.u===1)+wire([[541,281],[650,281],[650,189],[745,189]],s.v===1)+wire([[650,281],[650,326],[710,326],[710,313],[745,313]],s.v===1)+wire([[710,326],[710,339],[745,339]],s.v===1)+node(650,281)+node(710,326);
 b+=wire([[811,176],[910,176]],s.F1===1)+wire([[811,326],[910,326]],s.F2===1)+txt(35,115,'x = '+s.a,'ar-math')+txt(35,325,'y = '+s.b,'ar-math')+txt(320,210,'t '+(s.t??'?'),'ar-math')+txt(570,99,'u '+(s.u??'?'),'ar-math')+txt(565,267,'v '+(s.v??'?'),'ar-math')+txt(845,151,'F1 '+(s.F1??'?'),'ar-math')+txt(845,364,'F2 '+(s.F2??'?'),'ar-math');return svg(b+'</g>',460,'nand-half-subtractor');}
function makeModel(id,title,spec){let {operation:op,n=4,a=11,b=5,c=0,z=6}=spec;const integer=x=>Number.isSafeInteger(x);if(![n,a,b,c,z].every(integer)||n<1||n>8||c<0||c>1)throw Error('Use an integer width from one to eight and a carry of zero or one.');if(!['full','ripple','prefix','select','subtract','compare','bcd','csa','multiply','division','booth','nand'].includes(op))throw Error('Unknown arithmetic operation.');let max=2**n-1;if(a<0||b<0||a>max||b>max||z<0||z>max)throw Error('All unsigned word inputs must fit the selected width.');if(['full','nand'].includes(op)&&(a>1||b>1))throw Error('Gate models require a and b to be single bits.');if(op==='bcd'&&(a>9||b>9))throw Error('BCD digits must be zero through nine.');if(op==='select'&&n!==8)throw Error('This carry-select schematic uses the specified four-plus-four eight-bit split.');if(op==='division'&&b===0)throw Error('Division by zero has no ordinary quotient or remainder.');
 const reasons={full:'Each computed signal preserves a+b+c=sum+2carry. Generated carry and XOR-propagated carry cannot both be one.',ripple:'Only an established carry may enter the next column. Local counts conserve binary weight; the final extra carry remains separate from signed overflow.',subtract:'Complementing B and supplying initial carry one computes A minus B modulo the word width. Final carry means no unsigned borrow.',prefix:'A higher interval consumes the carry function of its adjacent lower interval. Ordered composition preserves every possible incoming carry.',select:'Both high candidates are independent of the actual low carry. Selection chooses the complete high sum and its carry, rather than recomputing that block.',compare:'A differing high bit outweighs the combined possible differences in every lower bit. Equal high bits permit continued inspection.',bcd:'Valid digit totals range from zero through nineteen. Decimal carry q detects the threshold ten; the second binary carry alone is insufficient.',csa:'Each column counts three equal-weight bits independently. Its sum remains in that column and its carry contributes twice that column weight.',multiply:'Every partial product has weight 2^(i+j). Shifted rows are accumulated as exact integers without discarding the reserved product width.',booth:'The digit is lower bit minus current bit. Its signed weighted row contributes to the exact product, including the minimum-negative boundary.',division:'The trial 2R+x is below twice the positive divisor, so one comparison and at most one subtraction preserve the prefix identity and remainder bound.',nand:'NAND inversion and tied inputs are evaluated in the original topology. The final outputs implement difference parity and the borrow of x minus y.'};
 const frames=[],s={n,a,b,c,z},invariant='Every checkpoint obeys exact fixed-width arithmetic and its stated representation.';let result;
 function emit(caption,draw,formula){const ss=cp(s);frames.push({svg:draw(ss),caption,formula:formula??'',snapshot:ss,teaching:{currentState:ss,operation:caption,why:reasons[op],reading:'Read input values first, then the highlighted dependency, and finally the exact state below.',checks:[]}});}
 if(op==='full'){emit('Inputs are established; internal signals are not yet computed.',fullSVG);s.p=a^b;s.g=a&b;emit('Compute parity p and generated carry g independently.',fullSVG,'p=a\\oplus b,\\quad g=ab');s.h=s.p&c;s.sum=s.p^c;emit('Combine the incoming carry with p to form sum and propagated carry.',fullSVG);s.carry=s.g|s.h;emit('Merge the two carry terms and verify the weighted count.',fullSVG,'a+b+c=s+2d');result={sum:s.sum,carry:s.carry};}
 if(['ripple','subtract'].includes(op)){s.effectiveB=op==='subtract'?max^b:b;s.c=op==='subtract'?1:c;s.columns=[];let carry=s.c,sum=0;emit('Establish inputs and incoming carry; no column result is assumed.',q=>rippleSVG(q,op==='subtract'));for(let i=0;i<n;i++){let ai=bit(a,i),bi=bit(s.effectiveB,i),total=ai+bi+carry,si=total&1,out=total>>1;s.columns.push({i,a:ai,b:bi,in:carry,sum:si,out});sum+=si*2**i;carry=out;s.sum=sum;s.carry=carry;emit('Column '+i+' satisfies a+b+cin=sum+2cout; pass cout to the next column.',q=>rippleSVG(q,op==='subtract'),'a_i+b_i+c_i=s_i+2c_{i+1}');}let as=signed(a,n),bs=signed(b,n),exact=op==='subtract'?as-bs:as+bs+c;s.signedExact=exact;s.overflow=Number(exact< -(2**(n-1))||exact>2**(n-1)-1);result={sum,carry,borrow:op==='subtract'?1-carry:null,overflow:s.overflow,negative:bit(sum,n-1),zero:Number(sum===0),signedExact:exact};}
 if(op==='prefix'){s.levels=[Array.from({length:n},(_,i)=>({high:i,low:i,g:bit(a,i)&bit(b,i),p:bit(a,i)^bit(b,i)}))];emit('Form each single-column generate/propagate pair.',prefixSVG);for(let d=1;d<n;d*=2){let old=s.levels.at(-1),next=old.map((H,i)=>{if(i<d)return cp(H);let L=old[i-d];return{high:H.high,low:L.low,g:H.g|(H.p&L.g),p:H.p&L.p};});s.levels.push(next);emit('Combine adjacent ordered intervals of maximum span '+(2*d)+'.',prefixSVG,'G=G_H\\lor P_HG_L,\\quad P=P_HP_L');}let row=s.levels.at(-1);s.carries=[c,...row.map(r=>r.g|(r.p&c))];s.output=s.carries[n];s.sum=Array.from({length:n},(_,i)=>(bit(a,i)^bit(b,i)^s.carries[i])*2**i).reduce((x,y)=>x+y,0);emit('Apply the external carry to every prefix, then form each sum bit.',prefixSVG);result={sum:s.sum,carry:s.output,carries:s.carries};}
 if(op==='select'){emit('Two speculative high results and the actual low carry are initially pending.',selectSVG);let lo=(a&15)+(b&15)+c;s.low=lo&15;s.c4=lo>>4;emit('Compute the ordinary low block and its actual carry C4.',selectSVG);s.high0=(a>>4)+(b>>4);s.high1=s.high0+1;emit('Both high block results are computed independently of actual C4.',selectSVG);s.highSelected=s.c4?s.high1:s.high0;s.result=(s.highSelected&15)*16+s.low;s.finalCarry=s.highSelected>>4;emit('C4 selects the high sum and outgoing carry together.',selectSVG);result={sum:s.result,carry:s.finalCarry,fullAdders:12,multiplexers:5};}
 if(op==='compare'){s.inspected=0;s.decision='undecided';emit('No prefix has been inspected.',compareSVG);for(let i=n-1;i>=0;i--){s.inspected++;if(bit(a,i)!==bit(b,i)){s.decision=bit(a,i)?'A > B':'A < B';emit('Bit '+i+' is the first differing bit; it decides the order.',compareSVG);break;}s.decision=s.inspected===n?'A = B':'equal prefix; continue';emit('Bit '+i+' is equal; only then may the next lower bit be inspected.',compareSVG);}result={less:Number(a<b),equal:Number(a===b),greater:Number(a>b)};}
 if(op==='bcd'){emit('Valid decimal digits and incoming decimal carry are established.',bcdSVG);let total=a+b+c;s.k=total>>4;s.z=total&15;emit('The first adder produces a binary carry and low nibble.',bcdSVG);s.q=s.k|(bit(s.z,3)&bit(s.z,2))|(bit(s.z,3)&bit(s.z,1));emit('Detect an initial carry or a low digit greater than nine.',bcdSVG,'q=k\\lor z_3z_2\\lor z_3z_1');s.corrected=s.z+6*s.q;s.digit=s.corrected&15;s.secondCarry=s.corrected>>4;emit('Add six when q=1; retain q as the decimal carry.',bcdSVG);result={digit:s.digit,decimalCarry:s.q,initialCarry:s.k,correctionCarry:s.secondCarry,total};}
 if(op==='csa'){s.done=[];s.sum=0;s.carry=0;emit('Three equal-width rows enter independent column counters.',csaSVG);for(let i=0;i<n;i++){let total=bit(a,i)+bit(b,i)+bit(z,i);s.sum+=(total&1)*2**i;s.carry+=(total>>1)*2**i;s.done.push(i);emit('Count column '+i+'; its carry has weight 2^'+(i+1)+'.',csaSVG,'X+Y+Z=S+2C');}result={sum:s.sum,carry:s.carry,total:s.sum+2*s.carry};}
 if(op==='multiply'){s.done=0;s.total=0;s.rows=[];emit('Align every partial product to column i+j.',multiplySVG);for(let i=0;i<n;i++){let row=bit(b,i)?a*2**i:0;s.rows.push(row);s.total+=row;s.done++;emit('Add shifted row '+i+' of value '+row+' to the exact partial total.',multiplySVG); }result={product:s.total,rows:s.rows};}
 if(op==='division'){s.rows=[];s.prefix=0;s.Q=0;s.R=0;emit('Empty prefix has quotient zero and remainder zero.',divideSVG,'P=DQ+R');for(let i=n-1;i>=0;i--){const x=bit(a,i),u=2*s.R+x,q=Number(u>=b);s.prefix=2*s.prefix+x;s.Q=2*s.Q+q;s.R=u-q*b;s.rows.push({x,prefix:s.prefix,u,q,Q:s.Q,R:s.R});emit('Consume bit '+i+': trial '+u+(q?' reaches D, so subtract D.':' is below D, so retain it.'),divideSVG,'P=DQ+R,\\quad 0\\le R<D');}result={quotient:s.Q,remainder:s.R};}
 if(op==='booth'){s.as=signed(a,n);s.bs=signed(b,n);s.rows=[];s.total=0;emit('Start with exact signed operands and implicit lower bit zero.',boothSVG);for(let i=0;i<n;i++){let hi=bit(b,i),lo=i?bit(b,i-1):0,d=lo-hi,row=d*s.as*2**i;s.total+=row;s.rows.push({i,pair:''+hi+lo,d,row,total:s.total});emit('Position '+i+': pair '+hi+lo+' yields digit '+d+' and weighted row '+row+'.',boothSVG,'B_s=\\sum_{i=0}^{n-1}(b_{i-1}-b_i)2^i');}result={signedProduct:s.total,outputEncoding:(s.total+2**(2*n))%2**(2*n),temporaryWidth:n+1};}
 if(op==='nand'){emit('Establish inputs to the original NAND topology.',nandSVG);s.t=1-(a&b);emit('First NAND computes t=NOT(xy).',nandSVG);s.u=1-(a&s.t);s.v=1-(b&s.t);emit('Second level establishes u and v; v also feeds the tied-input inverter.',nandSVG);s.F1=1-(s.u&s.v);s.F2=1-s.v;emit('F1 is difference XOR; F2 is the borrow of x minus y.',nandSVG);result={difference:s.F1,borrow:s.F2};}
 if(!frames.length)throw Error('No checked model was constructed.');return{id,title,kind:frames[0].svg.match(/data-model-kind="([^"]+)/)[1],invariant,spec:cp(spec),frames,result};
}
if(typeof module!=='undefined')module.exports={makeModel,signed};
if(typeof document==='undefined')return;
function mathText(s){return '<math xmlns="http://www.w3.org/1998/Math/MathML"><mtext>'+esc(s)+'</mtext></math>';}
function mount(host,m){
 if(!host.querySelector('.ar-controls')){const controls=document.createElement('div');controls.className='ar-controls';controls.innerHTML='<button type="button" data-reset>Restart</button><button type="button" data-prev>Previous</button><button type="button" data-play>Play</button><button type="button" data-next>Next</button><label>Speed<select data-speed></select></label><label>Step<input type="range" data-seek min="0" value="0"></label>';host.querySelector('.ar-stage').before(controls);}
 for(const cls of ['ar-caption','ar-formula','ar-print'])if(!host.querySelector('.'+cls)){const part=document.createElement(cls==='ar-caption'?'p':'div');part.className=cls;host.append(part);}
 return AdvancedSimulations.mount(host,m,{topic:'g_arithmetic',prefix:'ar',retainDrawing:true});
}
async function boot(){const data=await(await fetch('g_arithmetic-models.json')).json();globalThis.ArithmeticPlayers=[];for(const host of document.querySelectorAll('[data-ar-model]')){const m=data.models.find(m=>m.id===host.dataset.arModel);if(!m)throw Error('Missing arithmetic model.');ArithmeticPlayers.push(mount(host,m));}
 const form=document.querySelector('#ar-form'),out=document.querySelector('#ar-output'),error=document.querySelector('#ar-error');let current=null;
 form.addEventListener('submit',event=>{event.preventDefault();try{const f=form.elements,spec={operation:f.operation.value,n:Number(f.n.value),a:Number(f.a.value),b:Number(f.b.value),c:Number(f.c.value),z:Number(f.z.value)},m=makeModel('editable-arithmetic','Your checked '+spec.operation+' circuit',spec);for(const frame of m.frames)frame.formulaHtml=mathText(frame.caption);current?.dispose();out.innerHTML='<section class="ar-model"><h3>'+esc(m.title)+'</h3><p>Dependency checkpoints are exact logical states, not electrical timing.</p><div class="ar-stage"></div></section><section class="lab-results"><h3>Final checked result</h3><pre>'+esc(JSON.stringify(m.result,null,2))+'</pre></section>';current=mount(out.firstChild,m);globalThis.ArithmeticLab=current;error.textContent='';}catch(e){error.textContent=e.message;}});form.dispatchEvent(new Event('submit',{cancelable:true}));
}
boot().catch(e=>{const p=document.createElement('p');p.setAttribute('role','alert');p.textContent='Arithmetic laboratory failed: '+e.message;document.querySelector('.lesson').prepend(p);throw e;});
})();
